function [y] = dtm_decimal_year(utc)
%DTM_DECIMAL_YEAR  The decimal year of +atmos/dtm2020_research.m (leap-year aware, through datenum).
%   utc: real[1][6] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    y0 = utc(1);
    d0 = asils.models.timescales.datenum(y0, 1, 1, 0, 0, 0);
    d1 = asils.models.timescales.datenum((y0 + 1), 1, 1, 0, 0, 0);
    y = (y0 + ((asils.models.timescales.datenum(utc(1), utc(2), utc(3), utc(4), utc(5), utc(6)) - d0) / (d1 - d0)));
end
